using System;using System.IO;using System.Linq;using System.Runtime.InteropServices;using System.Reflection;using NAudio.Wave;using NAudio.Wave.SampleProviders;using AirBridge.Routing;
class OutputFormatTests {
 static int passed;static void Check(bool ok,string name){if(!ok)throw new Exception(name);passed++;Console.WriteLine("PASS "+name);}
 sealed class Pcm:IWaveProvider {public WaveFormat WaveFormat{get;private set;}public int ReadFrames;readonly short left,right;public Pcm(int channels=2,short left=8192,short right=-16384){WaveFormat=new WaveFormat(44100,16,channels);this.left=left;this.right=right;}public int Read(byte[] b,int o,int count){int frames=count/WaveFormat.BlockAlign;for(int f=0;f<frames;f++)for(int c=0;c<WaveFormat.Channels;c++){short v=c==0?left:right;b[o++]=(byte)v;b[o++]=(byte)(v>>8);}ReadFrames+=frames;return frames*WaveFormat.BlockAlign;}}
 static byte[] Read(IWaveProvider p,int frames=1){var b=new byte[frames*p.WaveFormat.BlockAlign];int n=p.Read(b,0,b.Length);Check(n==b.Length,"converted output supplies complete aligned frames");return b;}
 static WaveFormatExtensible Ext(int rate,int bits,int channels){return new WaveFormatExtensible(rate,bits,channels);}
 static bool Reject(Action a){try{a();return false;}catch(NotSupportedException){return true;}}
 static void Run(){
  var source=new Pcm();var unity=OutputFormatAdapter.Convert(source,source.WaveFormat);Check(Object.ReferenceEquals(unity,source)&&source.ReadFrames==0,"unity PCM16 remains bit-exact and negotiation consumes no audio");
  var target=Ext(44100,32,2);var p=OutputFormatAdapter.Convert(source,target);var b=Read(p);Check(Object.ReferenceEquals(p.WaveFormat,target),"exact extensible output format is preserved");Check(BitConverter.ToSingle(b,0)==.25f&&BitConverter.ToSingle(b,4)==-.5f,"PCM16 to float preserves channel amplitude and order");
  var mono=Read(OutputFormatAdapter.Convert(new Pcm(),new WaveFormat(44100,16,1)));Check(BitConverter.ToInt16(mono,0)==-4096,"stereo downmix averages both channels");
  var stereo=Read(OutputFormatAdapter.Convert(new Pcm(1),WaveFormat.CreateIeeeFloatWaveFormat(44100,2)));Check(BitConverter.ToSingle(stereo,0)==.25f&&BitConverter.ToSingle(stereo,4)==.25f,"mono input duplicates safely to stereo");
  var pcm8=Read(OutputFormatAdapter.Convert(new Pcm(),new WaveFormat(44100,8,2)));Check(pcm8[0]==160&&pcm8[1]==64,"PCM8 unsigned encoding");
  var pcm24=Read(OutputFormatAdapter.Convert(new Pcm(),new WaveFormat(44100,24,2)));Check(pcm24.SequenceEqual(new byte[]{0,0,32,0,0,192}),"PCM24 packed little-endian encoding");
  var pcm32=Read(OutputFormatAdapter.Convert(new Pcm(),new WaveFormat(44100,32,2)));Check(BitConverter.ToInt32(pcm32,0)==536870912&&BitConverter.ToInt32(pcm32,4)==-1073741824,"PCM32 encoding retains signed full scale");
  var packed=Ext(44100,32,2);typeof(WaveFormatExtensible).GetField("subFormat",BindingFlags.NonPublic|BindingFlags.Instance).SetValue(packed,new Guid("00000001-0000-0010-8000-00aa00389b71"));typeof(WaveFormatExtensible).GetField("wValidBitsPerSample",BindingFlags.NonPublic|BindingFlags.Instance).SetValue(packed,(short)24);var valid=Read(OutputFormatAdapter.Convert(new Pcm(),packed));Check(BitConverter.ToInt32(valid,0)==536870912&&(valid[0]|valid[4])==0,"24 valid bits in 32-bit PCM container are left-aligned");
  var surround=Read(OutputFormatAdapter.Convert(new Pcm(),Ext(44100,32,6)));Check(BitConverter.ToSingle(surround,0)==.25f&&BitConverter.ToSingle(surround,4)==-.5f&&surround.Skip(8).All(x=>x==0),"surround output uses front L/R without duplicating into other speakers");
  Check(Reject(()=>OutputFormatAdapter.Convert(new Pcm(),new WaveFormat(44100,20,2))),"unsupported encoding is rejected before playing");
  var s=new Pcm();var rate=OutputFormatAdapter.Convert(s,Ext(48000,32,2));var second=Read(rate,48000);Check(s.ReadFrames>=44090&&s.ReadFrames<44250,"48k output consumes approximately one second of 44.1k input");Check(second.Skip(800).Any(x=>x!=0),"resampled signal is not silent");
  var odd=new byte[37];int n=OutputFormatAdapter.Convert(new Pcm(),target).Read(odd,3,29);Check(n==24&&odd.Take(3).All(x=>x==0)&&odd.Skip(27).All(x=>x==0),"unaligned requests do not overwrite offsets or partial frames");
  source=new Pcm();int attempts=0;var selected=OutputFormatAdapter.Initialize(source,Ext(48000,32,2),"Demo speaker",f=>true,w=>{attempts++;if(attempts==1)throw new COMException("尚未实现",unchecked((int)0x88890008));},null);Check(attempts==2&&selected.WaveFormat.Encoding==WaveFormatEncoding.IeeeFloat&&source.ReadFrames==0,"failed extensible initialize falls back to equivalent standard format without consuming audio");
  attempts=0;try{OutputFormatAdapter.Initialize(new Pcm(),target,"Busy speaker",f=>true,w=>{attempts++;throw new COMException("busy",unchecked((int)0x8889000A));},null);throw new Exception("expected error");}catch(PlaybackOutputException ex){Check(attempts==1&&ex.Message.Contains("Busy speaker")&&ex.Message.Contains("占用")&&ex.Message.Contains("0x8889000A"),"non-format failures are not retried and identify the device and code");}
  try{OutputFormatAdapter.Initialize(new Pcm(),target,"Rejecting speaker",f=>false,w=>{throw new Exception("must not initialize");},null);throw new Exception("expected error");}catch(PlaybackOutputException ex){Check(ex.GetBaseException()==ex&&ex.Message.Contains("不接受")&&!ex.Message.Contains("尚未实现")&&PlaybackOutputException.Display(ex,true).Contains("unsupported audio format"),"UI receives an explicit localized error instead of the raw COM description");}
  attempts=0;try{OutputFormatAdapter.Initialize(new Pcm(),target,"Stale Bluetooth endpoint",f=>true,w=>{attempts++;throw new COMException("尚未实现",unchecked((int)0x88890008));},null);throw new Exception("expected error");}catch(PlaybackOutputException ex){Check(ex.NativeFormatRejected&&ex.Message.Contains("自身系统混音格式")&&!ex.Message.Contains("尚未实现")&&attempts==3,"driver query/initialize contradiction is reported explicitly after bounded format attempts");}
  attempts=0;OutputFormatAdapter.Initialize(new Pcm(),target,"Quiet diagnostics",f=>true,w=>attempts++,x=>{throw new IOException("disk failed");});Check(attempts==1,"diagnostic failures cannot interrupt output initialization");
  var rates=new[]{16000,44100,48000,96000};foreach(int r in rates){var input=new Pcm();var converted=OutputFormatAdapter.Convert(input,WaveFormat.CreateIeeeFloatWaveFormat(r,1));var chunk=new byte[(r/100)*4];for(int i=0;i<100;i++){int read=converted.Read(chunk,0,chunk.Length);if(read!=chunk.Length)throw new Exception("short resample");}Check(Math.Abs(input.ReadFrames-44100)<150,"one-second streaming conversion has the expected rate ratio at "+r+" Hz");}
  Console.WriteLine("PASS output format total="+passed+"; deterministic PCM only, no system endpoints opened");
 }
 static int Main(){try{Run();return 0;}catch(Exception ex){Console.WriteLine("FAIL "+ex);return 1;}}
}
